local frequentSpellDescriptions = {
    [16179] = { en = "Reduces the Mana cost of your healing spells by $m1% and improves your chance to hit by $m2%.", description = "Riduce del $m1% il costo in mana dei tuoi incantesimi di cura e aumenta del $m2% la probabilità di colpire." },
    [16181] = { en = "Gives you a $m1% chance to avoid interruption caused by damage while casting any healing spell.", description = "Hai una probabilità del $m1% di evitare interruzioni causate dai danni mentre lanci un incantesimo di cura." },
    [16182] = { en = "Reduces the casting time of your Healing Wave spell by ${$m1/-1000}.1 sec.", description = "Riduce di ${$m1/-1000}.1 sec. il tempo di lancio di Onda Curativa." },
    [16184] = { en = "Reduces the cooldown of your Reincarnation spell by ${$m1/-60000} min, increases your maximum health by $m2%, and increases the amount of health and Mana you reincarnate with by an additional $m3%.", description = "Riduce di ${$m1/-60000} min il tempo di recupero di Reincarnazione, aumenta la salute massima del $m2% e aumenta di un ulteriore $m3% la salute e il mana con cui reincarni." },
    [16187] = { en = "Increases the effect of your Mana Spring Totem by $m1% and increases the effect of your Healing Stream Totem by $m2%.", description = "Aumenta del $m1% l’effetto del Totem della Fonte di Mana e del $m2% quello del Totem del Flusso Curativo." },
    [16190] = { en = "Summons a Mana Tide Totem with $s1 health at the feet of the caster for ${$d-1} sec that restores $16191s1 mana every $16191t1 seconds to group members within $16191a1 yards.", description = "Evoca ai piedi dell’incantatore un Totem della Marea di Mana con $s1 salute per ${$d-1} sec. Ripristina $16191s1 mana ogni $16191t1 secondi ai membri del gruppo entro $16191a1 metri." },
    [16194] = { en = "Increases the critical effect chance of your healing spells by $m1%.", description = "Aumenta del $m1% la probabilità di effetto critico dei tuoi incantesimi di cura." },
    [16196] = { en = "Improves your chance to hit by $m1%.", description = "Aumenta del $m1% la probabilità di colpire." },
    [16254] = { en = "Increases your chance to dodge by an additional $m1%.", description = "Aumenta di un ulteriore $m1% la probabilità di schivare." },
    [16255] = { en = "Improves your chance to get a critical strike with all spells and attacks by $m1%.", description = "Aumenta del $m1% la probabilità di colpo critico con tutti gli incantesimi e gli attacchi." },
    [16256] = { en = "Increases your attack speed by $m1% for your next $16257n swings after dealing a melee critical strike.", description = "Dopo un colpo critico in mischia, aumenta del $m1% la velocità d’attacco per i prossimi $16257n colpi." },
    [16258] = { en = "Increases the amount of damage reduced by your Stoneskin Totem and Windwall Totem by $m1% and reduces the cooldown of your Grounding Totem by ${$m2/-1000} sec.", description = "Aumenta del $m1% i danni assorbiti dai totem Pelle di Pietra e Muro di Vento e riduce di ${$m2/-1000} sec. il recupero del Totem di Radicamento." },
    [16261] = { en = "Increases the damage done by your Lightning Shield orbs by $m1%.", description = "Aumenta del $m1% i danni inflitti dalle sfere del tuo Scudo di Fulmini." },
    [16262] = { en = "Reduces the cast time of your Ghost Wolf spell by ${$m1/-1000}.1 sec, and Ghost Wolf may be used indoors.", description = "Riduce di ${$m1/-1000}.1 sec. il tempo di lancio di Lupo Spettrale, utilizzabile anche al chiuso." },
    [16266] = { en = "Increases the melee attack power bonus of your Rockbiter Weapon by $m1%, your Windfury Weapon effect by $m3% and increases the damage caused by your Flametongue Weapon and Frostbrand Weapon by $m2%.", description = "Aumenta del $m1% il bonus alla potenza d’attacco in mischia di Arma Rocciadura, del $m3% l’effetto di Arma Folgore e del $m2% i danni di Arma Lingua di Fuoco e Arma Gelocanto." },
    [16268] = { en = "Gives a chance to parry enemy melee attacks, reduces all threat generated by your attacks by $s1% while Rockbiter Weapon is not active, and increases all threat generated by $s3% while Rockbiter Weapon is active.", description = "Conferisce una probabilità di parare gli attacchi in mischia nemici, riduce del $s1% la minaccia generata quando Arma Rocciadura non è attiva e la aumenta del $s3% quando è attiva." },
    [16314] = { en = "Imbue the Shaman's weapon, increasing melee attack power by $16311s1 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.", description = "Infondi l’arma dello Sciamano: aumenta di $16311s1 la potenza d’attacco in mischia e permette agli attacchi con quell’arma di generare minaccia aggiuntiva. Dura 60 minuti." },
    [16315] = { en = "Imbue the Shaman's weapon, increasing melee attack power by $16312s1 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.", description = "Infondi l’arma dello Sciamano: aumenta di $16312s1 la potenza d’attacco in mischia e permette agli attacchi con quell’arma di generare minaccia aggiuntiva. Dura 60 minuti." },
    [16316] = { en = "Imbue the Shaman's weapon, increasing melee attack power by $16313s1 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.", description = "Infondi l’arma dello Sciamano: aumenta di $16313s1 la potenza d’attacco in mischia e permette agli attacchi con quell’arma di generare minaccia aggiuntiva. Dura 60 minuti." },
    [16321] = { en = "Increases your chance to dodge by $s1% for $d.", description = "Aumenta del $s1% la probabilità di schivare per $d." },
    [16322] = { en = "Increases the target's attack speed by $s1% for $d.", description = "Aumenta del $s1% la velocità d’attacco del bersaglio per $d." },
    [16325] = { en = "Increase Frost resistance by $s1 for $d.", description = "Aumenta di $s1 la resistenza al gelo per $d." },
    [16339] = { en = "Imbue the Shaman's weapon with fire. Each hit causes ${$10445m1/77-1} to ${$10445m1/25} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. When applied to main hand, disables any benefit you personally receive from Flametongue Totem. Lasts for 60 minutes.", description = "Infondi l’arma dello Sciamano con il fuoco. Ogni colpo infligge da ${$10445m1/77-1} a ${$10445m1/25} danni da fuoco aggiuntivi, in base alla velocità dell’arma. Le armi lente infliggono più danni per colpo. Sulla mano principale, annulla il beneficio personale del Totem Lingua di Fuoco. Dura 60 minuti." },
    [16341] = { en = "Imbue the Shaman's weapon with fire. Each hit causes ${$16343m1/77-1} to ${$16343m1/25} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. When applied to main hand, disables any benefit you personally receive from Flametongue Totem. Lasts for 60 minutes.", description = "Infondi l’arma dello Sciamano con il fuoco. Ogni colpo infligge da ${$16343m1/77-1} a ${$16343m1/25} danni da fuoco aggiuntivi, in base alla velocità dell’arma. Le armi lente infliggono più danni per colpo. Sulla mano principale, annulla il beneficio personale del Totem Lingua di Fuoco. Dura 60 minuti." },
    [16342] = { en = "Imbue the Shaman's weapon with fire.  Each hit causes ${$16344m1/77-1} to ${$16344m1/25} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. When applied to main hand, disables any benefit you personally receive from Flametongue Totem. Lasts for 60 minutes.", description = "Infondi l’arma dello Sciamano con il fuoco.  Ogni colpo infligge da ${$16344m1/77-1} a ${$16344m1/25} danni da fuoco aggiuntivi, in base alla velocità dell’arma. Le armi lente infliggono più danni per colpo. Sulla mano principale, annulla il beneficio personale del Totem Lingua di Fuoco. Dura 60 minuti." },
    [16355] = { en = "Imbue the Shaman's weapon with frost.  Each hit has a chance of causing $16352s2 additional Frost damage and slowing the target's movement speed by $16352s1% for $16352d.  Lasts for 60 minutes.", description = "Infondi l’arma dello Sciamano con il gelo.  Ogni colpo può infliggere $16352s2 danni da gelo aggiuntivi e ridurre del $16352s1% la velocità di movimento del bersaglio per $16352d.  Dura 60 minuti." },
    [16356] = { en = "Imbue the Shaman's weapon with frost.  Each hit has a chance of causing $16353s2 additional Frost damage and slowing the target's movement speed by $16353s1% for $16353d.  Lasts for 60 minutes.", description = "Infondi l’arma dello Sciamano con il gelo.  Ogni colpo può infliggere $16353s2 danni da gelo aggiuntivi e ridurre del $16353s1% la velocità di movimento del bersaglio per $16353d.  Dura 60 minuti." },
    [16362] = { en = "Imbue the Shaman's weapon with wind.  Each hit has a 20% chance of granting you $16361s2 extra $lattack:attacks; with $16361s1 extra melee attack power. When applied to main hand, disables any benefit you personally receive from Windfury Totem. Lasts for 60 minutes.", description = "Infondi l’arma dello Sciamano con il vento.  Ogni colpo ha il 20% di probabilità di conferirti $16361s2 $lattacco:attacchi; aggiuntivi e $16361s1 potenza d’attacco in mischia. Sulla mano principale, annulla il beneficio personale del Totem Folgore del Vento. Dura 60 minuti." },
    [16387] = { en = "Summons a Flametongue Totem with $s1 health at the feet of the caster. The totem enhances the melee attacks of all party members within $15036a1 yards. Each main hand hit causes ${$16389m1/77*$<mult>-1} to ${$16389M1/25*$<mult>} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. Lasts $d.", description = "Evoca un Totem Lingua di Fuoco con $s1 salute ai piedi dell’incantatore. Potenzia gli attacchi in mischia del gruppo entro $15036a1 metri. Ogni colpo della mano principale infligge da ${$16389m1/77*$<mult>-1} a ${$16389M1/25*$<mult>} danni da fuoco aggiuntivi, in base alla velocità dell’arma. Le armi lente infliggono più danni per colpo. Dura $d." },
    [16454] = { en = "Blasts a target for $s1 Fire damage and increases Fire damage done to target by $s2 for $d.", description = "Colpisce il bersaglio infliggendo $s1 danni da fuoco e aumenta di $s2 i danni da fuoco che subisce per $d." },
    [16487] = { en = "Regenerates $m1% of your total Health over $16488d after being the victim of a critical strike, dealing damage with Bloodthirst, or suffering more than $m2% of your maximum Health from a single attack.", description = "Rigenera il $m1% della salute totale nell’arco di $16488d dopo un colpo critico subito, danni inflitti con Sete di Sangue o un attacco singolo che sottrae oltre il $m2% della salute massima." },
    [16493] = { en = "Increases the critical strike damage bonus of your abilities by $s1%.", description = "Aumenta del $s1% il bonus ai danni da colpo critico delle tue abilità." },
    [16511] = { en = "An instant strike that deals $m4% weapon damage ($m5% if a Dagger is equipped) and causes the target to take $m3% increased Rupture damage from the Rogue. Lasts $d. Awards $s2 Combo $lPoint:Points;.", description = "Colpo istantaneo: infligge $m4% dei danni dell’arma ($m5% se equipaggi un pugnale) e aumenta del $m3% i danni da Lacerazione subiti dal bersaglio dal Ladro. Dura $d. Assegna $s2 punti combo ($lPoint:Points;)." },
    [16513] = { en = "Increases the damage dealt by your poisons by $m1% and gives your poisons an additional $m3% chance to resist dispel effects.", description = "Aumenta del $m1% i danni dei tuoi veleni e conferisce loro un’ulteriore probabilità del $m3% di resistere alla dissoluzione." },
    [16528] = { en = "Inflicts numbing pain that deals $m1 Nature damage every $t1 sec and increases time between target's attacks by $s2% for $d.", description = "Infligge dolore lancinante, causando $m1 danni naturali ogni $t1 sec. e aumentando del $s2% l’intervallo tra gli attacchi del bersaglio per $d." },
    [16538] = { en = "Increases all damage you deal by $s1% while a shield is equipped.", description = "Aumenta del $s1% tutti i danni che infliggi mentre hai uno scudo equipaggiato." },
    [16551] = { en = "All attacks are guaranteed to land and will be critical strikes for the next $d.", description = "Per i prossimi $d, tutti gli attacchi vanno a segno e sono colpi critici." },
    [16559] = { en = "Shoots a ring of fire dealing $s1 Fire damage to all nearby enemies, and envelops the caster with a Fire Shield for $16560d.", description = "Scaglia un anello di fuoco che infligge $s1 danni da fuoco ai nemici vicini e avvolge l’incantatore in uno Scudo di Fuoco per $16560d." },
    [16578] = { en = "Reduces the cast time of your Lightning Bolt, Chain Lightning, and Lava Burst spells by ${$m1/-1000}.2 sec.", description = "Riduce di ${$m1/-1000}.2 sec. il tempo di lancio di Dardo Fulminante, Catena di Fulmini e Eruzione Lavica." },
    [16611] = { en = "When struck has a $h% chance of stealing $16608o1 life from the attacker over $16608d.\r\n", description = "Quando subisci un colpo, hai una probabilità del $h% di sottrarre $16608o1 salute all’attaccante nell’arco di $16608d.\r\n" },
    [16620] = { en = "When struck in combat has a $H% chance to make you invulnerable to melee damage for $16621d. This effect can only occur once every $proccooldown sec.", description = "Quando subisci un colpo in combattimento, hai una probabilità del $H% di diventare immune ai danni in mischia per $16621d. Effetto attivabile una volta ogni $proccooldown sec." },
    [16689] = { en = "The next $n melee $Lattack:attacks; that $Lstrikes:strike; the caster will afflict the attacker with Entangling Roots (Rank 1). Castable while shapeshifted. Lasts $d.", description = "I prossimi $n attacchi in mischia che $Lattack:attacks; $Lstrikes:strike; l’incantatore infliggono all’attaccante Radici Avvolgenti (grado 1). Utilizzabile in forma mutata. Dura $d." },
    [16740] = { en = "Knocks nearby enemies back, stunning them for $d.", description = "Respinge i nemici vicini e li stordisce per $d." },
    [16757] = { en = "Increases the range of your Frostbolt and Blizzard spells and the radius of your Frost Nova and Cone of Cold spells by $s1%.", description = "Aumenta del $s1% la gittata di Dardo di Gelo e Tormenta e il raggio di Esplosione Gelida e Cono di Freddo." },
    [16810] = { en = "The next $n melee $Lattack:attacks; that $Lstrikes:strike; the caster will afflict the attacker with Entangling Roots (Rank 2). Castable while shapeshifted. Lasts $d.", description = "I prossimi $n attacchi in mischia che $Lattack:attacks; $Lstrikes:strike; l’incantatore infliggono all’attaccante Radici Avvolgenti (grado 2). Utilizzabile in forma mutata. Dura $d." },
    [16811] = { en = "The next $n melee $Lattack:attacks; that $Lstrikes:strike; the caster will afflict the attacker with Entangling Roots (Rank 3). Castable while shapeshifted. Lasts $d.", description = "I prossimi $n attacchi in mischia che $Lattack:attacks; $Lstrikes:strike; l’incantatore infliggono all’attaccante Radici Avvolgenti (grado 3). Utilizzabile in forma mutata. Dura $d." },
    [16812] = { en = "The next $n melee $Lattack:attacks; that $Lstrikes:strike; the caster will afflict the attacker with Entangling Roots (Rank 4). Castable while shapeshifted. Lasts $d.", description = "I prossimi $n attacchi in mischia che $Lattack:attacks; $Lstrikes:strike; l’incantatore infliggono all’attaccante Radici Avvolgenti (grado 4). Utilizzabile in forma mutata. Dura $d." },
    [16813] = { en = "The next $n melee $Lattack:attacks; that $Lstrikes:strike; the caster will afflict the attacker with Entangling Roots (Rank 5). Castable while shapeshifted. Lasts $d.", description = "I prossimi $n attacchi in mischia che $Lattack:attacks; $Lstrikes:strike; l’incantatore infliggono all’attaccante Radici Avvolgenti (grado 5). Utilizzabile in forma mutata. Dura $d." },
    [16819] = { en = "Increases the range of your offensive Balance spells by $m1% and improves your chance to hit by $m2%.", description = "Aumenta del $m1% la gittata degli incantesimi offensivi di Equilibrio e del $m2% la probabilità di colpire." },
    [16821] = { en = "Increases the damage and critical strike chance of your Moonfire spell by $s1%.", description = "Aumenta del $s1% i danni e la probabilità di colpo critico di Fuoco Lunare." },
    [16845] = { en = "Reduces the Mana cost of your damaging spells by $s1%.", description = "Riduce del $s1% il costo in mana dei tuoi incantesimi che infliggono danni." },
    [16864] = { en = "Your spells and attacks have a chance to grant you Clearcasting, reducing the Mana, Rage, or Energy cost of your next damage or healing spell or offensive ability by $16870s1%. Clearcasting is not consumed by Wrath or by spells or abilities that cost no resources.", description = "I tuoi incantesimi e attacchi possono conferirti Lancio Gratuito, riducendo del $16870s1% il costo in mana, rabbia o energia del prossimo incantesimo di danno o cura oppure abilità offensiva. Ira e abilità senza costo non consumano l’effetto." },
    [16873] = { en = "Holy power infuses the target increasing their Stamina by $M1 for $d.", description = "Il potere sacro pervade il bersaglio, aumentandone la Tempra di $M1 per $d." },
    [16880] = { en = "All non-periodic spell criticals grace you with a blessing of nature, increasing your spellcasting speed and reducing your global cooldown by $m1% for $16886d.", description = "I colpi critici non periodici con incantesimi ti conferiscono una benedizione della natura: aumenta del $m1% la velocità di lancio e riduce il recupero globale per $16886d." },
    [16896] = { en = "Increases the damage done by your Arcane and Nature spells by $m1%.", description = "Aumenta del $m1% i danni dei tuoi incantesimi arcani e naturali." },
    [16909] = { en = "Increases the critical strike damage bonus of your Arcane and Nature spells by $m1%.", description = "Aumenta del $m1% il bonus ai danni critici dei tuoi incantesimi arcani e naturali." },
    [16914] = { en = "Creates a violent storm in the target area causing $1278965s1 Nature damage to enemies every $t3 sec, and increasing the time between attacks of enemies by $s2%. Lasts $d. Druid must channel to maintain the spell.", description = "Scatena una tempesta nell’area bersaglio, infliggendo $1278965s1 danni naturali ai nemici ogni $t3 sec. e aumentando del $s2% l’intervallo tra i loro attacchi. Dura $d. Il Druido deve incanalare l’incantesimo." },
    [16916] = { en = "Heal yourself for $s2 and increase your Strength by $s1 for $d.", description = "Ti cura di $s2 e aumenta la tua Forza di $s1 per $d." },
    [16918] = { en = "Increases the damage done by your Entangling Roots spell by $m1%, and its victims can take up to $m1% more damage without interrupting the effect.", description = "Aumenta del $m1% i danni di Radici Avvolgenti; i bersagli possono subire fino al $m1% di danni aggiuntivi senza interrompere l’effetto." },
    [16927] = { en = "Slows the target's movement speed by $s2% and increases the time between their attacks by $s1% for $d.", description = "Riduce del $s2% la velocità di movimento del bersaglio e aumenta del $s1% l’intervallo tra i suoi attacchi per $d." },
    [16929] = { en = "While in Bear Form, Cat Form, Dire Bear Form, or Moonkin Form, you gain $s2 additional base Armor per level and another ${$m1/100}.2 base Armor for each point of defense skill beyond five times your level. This amount can be further increased by multipliers from those forms.", description = "In Forma d’Orso, Felina, d’Orso Feroce o Lunagufo, ottieni $s2 armatura base aggiuntiva per livello e un ulteriore valore pari a ${$m1/100}.2 per punto di difesa oltre cinque volte il tuo livello. I moltiplicatori di queste forme possono aumentarlo ulteriormente." },
    [16939] = { en = "Chance on hit to grant nearby party members $s1% increased critical strike chance.", description = "Quando colpisci, puoi aumentare del $s1% la probabilità di colpo critico dei membri vicini del gruppo." },
    [16947] = { en = "Increases damage done by your Swipe ability by $s2% and reduces the chance enemies have to detect you while Prowling as if you were ${$m1/5} $llevel:levels; higher.", description = "Aumenta del $s2% i danni di Spazzata e riduce il rilevamento in Furtività come se fossi di ${$m1/5} $llevel:levels; più alto." },
    [16966] = { en = "Reduces the Energy cost of your Shred ability by $m1 and reduces the Rage cost of your Lacerate ability by ${$m2/-10}.", description = "Riduce di $m1 il costo in energia di Azzannamento e di ${$m2/-10} il costo in rabbia di Lacerazione." },
    [16968] = { en = "Reduces the Energy cost of your Shred ability by $s1.", description = "Riduce di $s1 il costo in energia di Azzannamento." },
    [16972] = { en = "Increases your melee Attack Power in Cat Form, Bear Form, and Dire Bear Form by $s1% of your level.", description = "Aumenta la potenza d’attacco in mischia in Forma Felina, d’Orso e d’Orso Feroce del $s1% del tuo livello." },
    [16979] = { en = "Charge an enemy, immobilizing them and interrupting any spell they are casting for $19675d.", description = "Carichi un nemico, immobilizzandolo e interrompendo il suo incantesimo per $19675d." },
    [16998] = { en = "Increases the damage caused by your Claw, Rake, Shred, Maul, and Swipe abilities by $s1%.", description = "Aumenta del $s1% i danni di Artiglio, Rake, Azzannamento, Percossa e Spazzata." },
    [17002] = { en = "Increases your movement speed while in Cat Form by $m2%, and increases your chance to Dodge by $m1%.", description = "Aumenta del $m2% la velocità di movimento in Forma Felina e del $m1% la probabilità di schivare." },
    [17003] = { en = "Increases your Intellect by $s1%.  In addition, while in Bear Form or Dire Bear Form your Stamina is increased by $s2% and while in Cat Form your Strength is increased by $s3%.", description = "Aumenta del $s1% il tuo Intelletto. In Forma d’Orso o d’Orso Feroce la Tempra aumenta del $s2%; in Forma Felina la Forza aumenta del $s3%." },
    [17007] = { en = "While in Cat Form, Bear Form, or Dire Bear Form, the Leader of the Pack increases the critical strike chance of all party members within $24932a1 yards by $24932s1%, exclusive with Moonkin Aura.", description = "In Forma Felina, d’Orso o d’Orso Feroce, Guida del Branco aumenta la probabilità di colpo critico di tutti i membri del gruppo entro $24932a1 metri del $24932s1%. Non cumulabile con Aura del Lunagufo." },
    [17063] = { en = "Gives you a $m1% chance to avoid interruption caused by damage while casting Arcane and Nature spells.", description = "Hai una probabilità del $m1% di evitare interruzioni causate dai danni mentre lanci incantesimi arcani e naturali." },
    [17074] = { en = "Increases the critical effect chance of your Regrowth spell by $s1%.", description = "Aumenta del $s1% la probabilità di effetto critico di Ricrescita." },
    [17104] = { en = "Increases the effect of all your healing spells by $s1%.", description = "Aumenta del $s1% l’effetto di tutti i tuoi incantesimi di cura." },
    [17111] = { en = "Increases the effect of your Rejuvenation spell by $s1%.", description = "Aumenta di $s1 l’effetto di Rinvigorimento." },
    [17118] = { en = "Reduces the threat generated by your Nature and Arcane spells by $s1%.", description = "Riduce del $s1% la minaccia generata dai tuoi incantesimi naturali e arcani." },
    [17123] = { en = "Reduces threat caused by Tranquility by $s1% and its cooldown by $m2%.", description = "Riduce del $s1% la minaccia di Tranquillità e del $m2% il suo tempo di recupero." },
    [17148] = { en = "Wounds the target's head, dealing $s1 Physical damage, and increasing the casting time of all spells by $s2% for $d.", description = "Ferisce la testa del bersaglio, infliggendo $s1 danni fisici e aumentando del $s2% il tempo di lancio degli incantesimi per $d." },
    [17245] = { en = "Increases the maximum number of targets you may have affected by Entangling Roots by $s1.", description = "Aumenta di $s1 il numero massimo di bersagli che puoi avere sotto l’effetto di Radici Avvolgenti." },
    [17252] = { en = "A protective mana shield surrounds the caster absorbing $s1 damage. While the shield holds, increases mana regeneration by $s2 every $t2 sec for $d.", description = "Uno scudo protettivo di mana avvolge l’incantatore e assorbe $s1 danni. Finché resiste, aumenta di $s2 la rigenerazione del mana ogni $t2 sec. per $d." },
    [17283] = { en = "Flick the lighter, dealing $s1 Fire damage to all enemies in a cone in front of you. Deals $s2 times as much damage to Plants.", description = "Usa l’accendino per infliggere $s1 danni da fuoco a tutti i nemici in un cono davanti a te. Le piante subiscono danni moltiplicati per $s2." },
    [17308] = { en = "Knocks target silly for $d1. Orcs and Ogres are stunned for $s2 times as long.", description = "Stordisce il bersaglio per $d1. Gli Orchi e gli Ogre restano storditi per un tempo moltiplicato per $s2." },
    [17315] = { en = "Punctures target's armor lowering it by $s1. Can be applied up to $u times.", description = "Perfora l’armatura del bersaglio, riducendola di $s1. L’effetto è cumulabile fino a $u volte." },
    [17322] = { en = "Increases the range of your offensive Shadow spells by $s1%.", description = "Aumenta del $s1% la gittata dei tuoi incantesimi d’Ombra offensivi." },
    [17329] = { en = "The next $n melee $Lattack:attacks; that $Lstrikes:strike; the caster will afflict the attacker with Entangling Roots (Rank 6). Castable while shapeshifted. Lasts $d.", description = "I prossimi $n attacchi in mischia che $Lattack:attacks; $Lstrikes:strike; l’incantatore infliggono all’attaccante Radici Avvolgenti (grado 6). Utilizzabile in forma mutata. Dura $d." },
    [17330] = { en = "Web yourself to the ground, preventing jumping and negating the next Knockback effect taken within $d.", description = "Ti avvolgi in una ragnatela a terra: non puoi saltare e annulli il prossimo effetto di respinta subito entro $d." },
    [17332] = { en = "Chance on Hit: Immobilizes the target and lowers their armor by $17333s2 for $17333d.", description = "All’impatto: immobilizza il bersaglio e riduce la sua armatura di $17333s2 per $17333d." },
    [17350] = { en = "Has a chance when struck in combat to increase your chance to block by $17351s1% for $17351d. Undead that strike you are $s2 times as likely to activate this effect.", description = "Quando subisci un colpo in combattimento, puoi aumentare del $17351s1% la probabilità di blocco per $17351d. I non morti hanno una probabilità $s2 volte maggiore di attivare l’effetto." },
    [17352] = { en = "Increases Attack Power by $s1, and Attack Power against Undead by an additional $s2 for $d.", description = "Aumenta la potenza d’attacco di $s1 e quella contro i non morti di ulteriori $s2 per $d." },
    [17354] = { en = "Summons a Mana Tide Totem with $s1 health at the feet of the caster for ${$d-1} sec that restores $17355s1 mana every $17355t1 seconds to group members within $17355a1 yards.", description = "Evoca ai piedi dell’incantatore un Totem della Marea di Mana con $s1 salute per ${$d-1} sec. Ripristina $17355s1 mana ogni $17355t1 secondi ai membri del gruppo entro $17355a1 metri." },
    [17359] = { en = "Summons a Mana Tide Totem with $s1 health at the feet of the caster for ${$d-1} sec that restores $17360s1 mana every $17360t1 seconds to group members within $17360a1 yards.", description = "Evoca ai piedi dell’incantatore un Totem della Marea di Mana con $s1 salute per ${$d-1} sec. Ripristina $17360s1 mana ogni $17360t1 secondi ai membri del gruppo entro $17360a1 metri." },
    [17364] = { en = "Instantly strike for normal weapon damage and increase the damage you deal to the target with your next Lightning Bolt, Chain Lightning, or Earth Shock spell by $s2% for $d.", description = "Colpisce all’istante con i normali danni dell’arma e aumenta del $s2% i danni che infliggi al bersaglio con il prossimo Dardo Fulminante, Catena di Fulmini o Shock Terrestre per $d." },
    [17401] = { en = "Creates a violent storm in the target area causing $1278968s1 Nature damage to enemies every $t3 sec, and increasing the time between attacks by $s2%. Lasts $d. Druid must channel to maintain the spell.", description = "Scatena una tempesta nell’area bersaglio, infliggendo $1278968s1 danni naturali ai nemici ogni $t3 sec. e aumentando del $s2% l’intervallo tra gli attacchi. Dura $d. Il Druido deve incanalare l’incantesimo." },
    [17402] = { en = "Creates a violent storm in the target area causing $1278759s1 Nature damage to enemies every $t3 sec, and increasing the time between attacks by $1278759s2%. Lasts $d. Druid must channel to maintain the spell.", description = "Scatena una tempesta nell’area bersaglio, infliggendo $1278759s1 danni naturali ai nemici ogni $t3 sec. e aumentando del $1278759s2% l’intervallo tra gli attacchi. Dura $d. Il Druido deve incanalare l’incantesimo." },
    [17448] = { en = "Restores $s1 health. Can only be used at $s2% health.", description = "Ripristina $s1 salute. Utilizzabile solo quando la salute è al $s2%." },
    [17485] = { en = "Increases your Intellect by $m1%.", description = "Aumenta del $m1% il tuo Intelletto." },
    [17494] = { en = "Decreases target's Attack Power by $s1 for $d1 and transfers it into Spirit to you.", description = "Riduce di $s1 la potenza d’attacco del bersaglio per $d1 e trasferisce a te il valore sottratto sotto forma di Spirito." },
    [17495] = { en = "Deals $17496s1 Physical damage every time you block.", description = "Infligge $17496s1 danni fisici ogni volta che blocchi." },
    [17501] = { en = "Hurls a fiery ball that causes $s1 Holy damage to Undead enemies.", description = "Scaglia una sfera infuocata che infligge $s1 danni sacri ai nemici non morti." },
    [17535] = { en = "Increases Intellect and Spirit by $s1 for $d.", description = "Aumenta Intelletto e Spirito di $s1 per $d." },
    [17537] = { en = "Increases Strength and Stamina by $s1 for $d.", description = "Aumenta Forza e Tempra di $s1 per $d." },
    [17538] = { en = "Increases Agility by $s1 and chance to get a critical hit by $s2%. Lasts for $d.", description = "Aumenta Agilità di $s1 e la probabilità di colpo critico del $s2%. Dura $d." },
    [17619] = { en = "Increases the effects that healing and mana potions have on the wearer by $s1%.", description = "Aumenta del $s1% l’efficacia delle pozioni di cura e mana su chi lo indossa." },
    [17624] = { en = "You turn to stone, protecting you from all physical attacks and spells for $d, but during that time you cannot attack, move or cast spells. You can only have the effect of one flask at a time.", description = "Ti trasformi in pietra, proteggendoti da tutti gli attacchi fisici e gli incantesimi per $d. Non puoi attaccare, muoverti o lanciare incantesimi. Puoi avere l’effetto di una sola fiasca alla volta." },
    [17625] = { en = "Increases movement speed by $s2% and restores $s1 health every $t1.", description = "Aumenta del $s2% la velocità di movimento e ripristina $s1 salute ogni $t1." },
    [17626] = { en = "Increases the player's maximum health by $s1 for $d. You can only have the effect of one flask at a time. This effect persists through death.", description = "Aumenta di $s1 la salute massima del giocatore per $d. L’effetto di una sola fiasca alla volta. Persiste dopo la morte." },
    [17627] = { en = "Increases the player's maximum Mana by $s1 for $d. You can only have the effect of one flask at a time. This effect persists through death.", description = "Aumenta di $s1 il mana massimo del giocatore per $d. L’effetto di una sola fiasca alla volta. Persiste dopo la morte." },
    [17628] = { en = "Increases damage done by magical spells and effects by up to $s1 for $d. You can only have the effect of one flask at a time. This effect persists through death.", description = "Aumenta fino a $s1 i danni degli incantesimi e degli effetti magici per $d. L’effetto di una sola fiasca alla volta. Persiste dopo la morte." },
    [17629] = { en = "Increases your resistance to all schools of magic by $s1 for $d. You can only have the effect of one flask at a time. This effect persists through death and stacks with all other resistance spells and items.", description = "Aumenta di $s1 la resistenza a tutte le scuole di magia per $d. L’effetto di una sola fiasca alla volta. Persiste dopo la morte e si cumula con gli altri incantesimi e oggetti di resistenza." },
    [17712] = { en = "Restores $s1 Health, increased by $s2% for each $s2% of your Health missing.", description = "Ripristina $s1 salute, aumentata del $s2% per ogni $s2% di salute mancante." },
    [17727] = { en = "Creates a Greater Spellstone which can be used to enchant your weapon with Shadow, increasing your spell haste by $1237164s2% and the damage done by your Shadow spells by up to $1237164s1.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra Incantesimo Superiore, utilizzabile per incantare l’arma con l’Ombra: aumenta del $1237164s2% la celerità degli incantesimi e fino a $1237164s1 i danni da Ombra.\r\n\r\nGli oggetti evocati scompaiono se resti disconnesso per più di 15 minuti." },
    [17728] = { en = "Creates a Major Spellstone which can be used to enchant your weapon with Shadow, increasing your spell haste by $1237165s2% and the damage done by your Shadow spells by up to $1237165s1.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra Incantesimo Maggiore, utilizzabile per incantare l’arma con l’Ombra: aumenta del $1237165s2% la celerità degli incantesimi e fino a $1237165s1 i danni da Ombra.\r\n\r\nGli oggetti evocati scompaiono se resti disconnesso per più di 15 minuti." },
    [17735] = { en = "Taunts all enemies within $a1 yards, increasing the chance that they will attack the Voidwalker.", description = "Provoca tutti i nemici entro $a1 metri, aumentando la probabilità che attacchino il Camminatore del Vuoto." },
    [17750] = { en = "Taunts all enemies within $a1 yards, increasing the chance that they will attack the Voidwalker.  More effective than Suffering (Rank 1).", description = "Provoca tutti i nemici entro $a1 metri, aumentando la probabilità che attacchino il Camminatore del Vuoto. Più efficace di Sofferenza (grado 1)." },
    [17751] = { en = "Taunts all enemies within $a1 yards, increasing the chance that they will attack the Voidwalker.  More effective than Suffering (Rank 2).", description = "Provoca tutti i nemici entro $a1 metri, aumentando la probabilità che attacchino il Camminatore del Vuoto. Più efficace di Sofferenza (grado 2)." },
    [17752] = { en = "Taunts all enemies within $a1 yards, increasing the chance that they will attack the Voidwalker.  More effective than Suffering (Rank 3).", description = "Provoca tutti i nemici entro $a1 metri, aumentando la probabilità che attacchino il Camminatore del Vuoto. Più efficace di Sofferenza (grado 3)." },
    [17783] = { en = "Gives you a $s1% chance to avoid interruption caused by damage while channeling or casting your Drain Life, Drain Mana, Drain Soul, or Wrack spells.", description = "Hai una probabilità del $s1% di evitare interruzioni causate dai danni mentre canalizzi o lanci Risucchio Vitale, Risucchio di Mana, Risucchio d’Anima o Tormento." },
    [17793] = { en = "Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by $m1% for $17794d.", description = "I colpi critici di Dardo d’Ombra aumentano del $m1% i danni da Ombra subiti dal bersaglio dai tuoi attacchi per $17794d." },
    [17804] = { en = "Increases the damage done or health drained by your Drain Life, Drain Soul, and Wrack spells by $s1% per each of your other Affliction effects active on the target, up to a maximum increase of ${$m1*3}%.", description = "Aumenta del $s1% i danni o la salute sottratta da Risucchio Vitale, Risucchio d’Anima e Tormento per ogni altro effetto di Afflizione attivo sul bersaglio, fino a un massimo del ${$m1*3}%." },
    [17877] = { en = "Instantly blasts the target for $s2 Shadow damage.  If a non-trivial target dies within $d of being hit with Shadowburn, the caster gains a Soul Shard.", description = "Colpisce istantaneamente il bersaglio infliggendo $s2 danni da ombra. Se un bersaglio che fornisce esperienza muore entro $d dopo Bruciatura d’Anima, l’incantatore ottiene una Scheggia d’Anima." },
    [17917] = { en = "Increases the range of your damaging spells by $s1%.", description = "Aumenta del $s1% la gittata dei tuoi incantesimi che infliggono danni." },
    [17927] = { en = "Increases the critical strike chance of your Searing Pain spell by $m1% and the damage done by all your Destruction spells by $m2%.", description = "Aumenta del $m1% la probabilità di colpo critico di Dolore Bruciante e del $m2% i danni dei tuoi incantesimi di Distruzione." },
    [17945] = { en = "Imbues your weapon with Fire, increasing your spell critical strike chance by $23481s2% and the damage done by your Fire spells by up to $23481s1.", description = "Infondi la tua arma con il fuoco: aumenta del $23481s2% la probabilità di colpo critico degli incantesimi e fino a $23481s1 i danni da fuoco." },
    [17947] = { en = "Imbues your weapon with Fire, increasing your spell critical strike chance by $23482s2% and the damage done by your Fire spells by up to $23482s1.", description = "Infondi la tua arma con il fuoco: aumenta del $23482s2% la probabilità di colpo critico degli incantesimi e fino a $23482s1 i danni da fuoco." },
    [17949] = { en = "Imbues your weapon with Fire, increasing your spell critical strike chance by $23483s2% and the damage done by your Fire spells by up to $23483s1.", description = "Infondi la tua arma con il fuoco: aumenta del $23483s2% la probabilità di colpo critico degli incantesimi e fino a $23483s1 i danni da fuoco." },
    [17951] = { en = "Creates a Firestone which can be used to enchant your weapon with Fire, increasing your spell critical strike chance by $23481s2% and the damage done by your Fire spells by up to $23481s1.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra di Fuoco per incantare l’arma con il fuoco: aumenta del $23481s2% la probabilità di colpo critico e fino a $23481s1 i danni da fuoco.\r\n\r\nGli oggetti evocati scompaiono dopo 15 minuti di disconnessione." },
    [17952] = { en = "Creates a Greater Firestone which can be used to enchant your weapon with Fire, increasing your spell critical strike chance by $23482s2% and the damage done by your Fire spells by up to $23482s1.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra di Fuoco Superiore per incantare l’arma con il fuoco: aumenta del $23482s2% la probabilità di colpo critico e fino a $23482s1 i danni da fuoco.\r\n\r\nGli oggetti evocati scompaiono dopo 15 minuti di disconnessione." },
    [17953] = { en = "Creates a Major Firestone which can be used to enchant your weapon with Fire, increasing your spell critical strike chance by $23483s2% and the damage done by your Fire spells by up to $23483s1.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra di Fuoco Maggiore per incantare l’arma con il fuoco: aumenta del $23483s2% la probabilità di colpo critico e fino a $23483s1 i danni da fuoco.\r\n\r\nGli oggetti evocati scompaiono dopo 15 minuti di disconnessione." },
    [17954] = { en = "Increases the damage done by your Fire spells by $m1% and reduces the cast time of your Searing Pain spell by ${$m3/-1000}.1 sec.", description = "Aumenta del $m1% i danni dei tuoi incantesimi di fuoco e riduce di ${$m3/-1000}.1 sec. il tempo di lancio di Dolore Bruciante." },
    [17959] = { en = "Increases the critical strike damage bonus of your Destruction spells by $s1%.", description = "Aumenta del $s1% il bonus ai danni critici dei tuoi incantesimi di Distruzione." },
    [18066] = { en = "Improves your chance to hit with attacks by ${$s1}.1%.", description = "Aumenta di ${$s1}.1% la probabilità di colpire con gli attacchi." },
    [18073] = { en = "Gives your Soul Fire spell a $s1% chance to Stun the target for $18093d, and your Rain of Fire and Hellfire spells a $s1% chance over their duration to Stun targets they damage for $18093d.", description = "Fuoco dell’Anima ha una probabilità del $s1% di stordire il bersaglio per $18093d; Pioggia di Fuoco e Inferno hanno una probabilità del $s1% durante la loro durata di stordire i bersagli per $18093d." },
    [18094] = { en = "Gives your Corruption, Drain Soul, Drain Life, and Wrack spells a $m1% chance to cause you to enter a Shadow Trance after damaging the opponent. The Shadow Trance reduces the casting time of your next Shadow Bolt spell by $17941s1%.", description = "Corruzione, Risucchio d’Anima, Risucchio Vitale e Tormento possono farti entrare in Trance d’Ombra con probabilità $m1% dopo aver danneggiato l’avversario. La trance riduce del $17941s1% il tempo di lancio del prossimo Dardo d’Ombra." },
    [18096] = { en = "Your non-periodic critical strikes with your Fire spells increase your Shadow damage done by $m1% for $18093d, and your non-periodic critical strikes with your Shadow spells increase your Fire damage done by $m1% for $18093d.", description = "I colpi critici non periodici degli incantesimi di fuoco aumentano del $m1% i danni da Ombra per $18093d; quelli degli incantesimi d’Ombra aumentano del $m1% i danni da fuoco per $18093d." },
    [18097] = { en = "When struck in combat has a 1% chance of raising a thorny shield that inflicts $17154s1 Nature damage to attackers when hit and increases Nature resistance by $17154s2 for $17154d.\r\n", description = "Quando subisci un colpo in combattimento, hai una probabilità dell’1% di evocare uno scudo di spine che infligge $17154s1 danni naturali agli attaccanti e aumenta di $17154s2 la resistenza alla natura per $17154d.\r\n" },
    [18100] = { en = "Encases the caster in a layer of frost that lasts $d. The thick ice increases armor by $s1, slows melee attackers' movement to $18101s2%, and increases the time between their attacks by $18101s1%.", description = "Avvolge l’incantatore in uno strato di gelo per $d. Il ghiaccio aumenta l’armatura di $s1, riduce al $18101s2% la velocità degli attaccanti in mischia e aumenta del $18101s1% l’intervallo tra i loro attacchi." },
    [18119] = { en = "Increases the initial damage of your Immolate spell by $m2% and your Conflagrate spell has a $m1% chance to Daze the target, reducing the target's movement speed by $18118m1% for $18118d.", description = "Aumenta del $m2% i danni iniziali di Immolazione. Incendio ha una probabilità del $m1% di disorientare il bersaglio, riducendone la velocità di movimento del $18118m1% per $18118d." },
    [18135] = { en = "Gives you a $s1% chance to resist interruption caused by damage while casting or channeling any Destruction spell.", description = "Hai una probabilità del $s1% di resistere alle interruzioni causate dai danni mentre lanci o canalizzi incantesimi di Distruzione." },
    [18174] = { en = "Improves your chance to hit by $m1% and reduces all threat you generate by $m3%.", description = "Aumenta del $m1% la probabilità di colpire e riduce del $m3% la minaccia generata." },
    [18230] = { en = "Restores $o1 health over $d.   Must remain seated while eating.   If you eat for 10 seconds will also increase your Agility by $18192s for $18192d.", description = "Ripristina $o1 salute in $d.   Devi restare seduto mentre mangi.   Dopo 10 secondi, aumenta l’Agilità di $18192s per $18192d." },
    [18231] = { en = "Restores $o1 health over $d.   Must remain seated while eating.   Also increases your Spirit by $18193s for $18193d.", description = "Ripristina $o1 salute in $d.   Devi restare seduto mentre mangi.   Aumenta lo Spirito di $18193s per $18193d." },
    [18232] = { en = "Restores $o1 health over $d.   Must remain seated while eating.   Also restores $18222s1 health every 5 seconds for $18222d.", description = "Ripristina $o1 salute in $d.   Devi restare seduto mentre mangi.   Ripristina anche $18222s1 salute ogni 5 secondi per $18222d." },
    [18271] = { en = "Increases the damage dealt or life drained by your Shadow spells by $s1%.", description = "Aumenta del $s1% i danni inflitti o la vita sottratta dai tuoi incantesimi d’Ombra." },
    [18288] = { en = "Increases the effect of your next Curse of Weakness or Bane of Agony by $s1%, or your next Curse of Exhaustion by $s2%.  Lasts $d.", description = "Aumenta del $s1% l’effetto della prossima Maledizione della Debolezza o dell’Agonia, oppure del $s2% quello della prossima Maledizione di Esaurimento.  Dura $d." },
    [18427] = { en = "Increases the damage of your Sinister Strike, Backstab, and Eviscerate abilities by $s1%.", description = "Aumenta del $s1% i danni di Attacco Funesto, Agguato ed Eviscerazione." },
    [18459] = { en = "Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico di Esplosione di Fuoco, Lancia di Ghiaccio, Esplosione Arcana e Scottatura." },
    [18499] = { en = "The warrior enters a berserker rage, becoming immune to Fear and Incapacitate effects and generating extra rage when taking damage.  Lasts $d.", description = "Il Guerriero entra in furia berserker, diventando immune a paura e incapacitazione e generando rabbia aggiuntiva quando subisce danni.  Dura $d." },
    [18550] = { en = "Increases your spell damage by $s1% and the critical strike chance of your offensive spells by $s1%.", description = "Aumenta del $s1% i danni degli incantesimi e del $s1% la probabilità di colpo critico degli incantesimi offensivi." },
    [18551] = { en = "Increases your total Intellect by $m1%.", description = "Aumenta del $m1% il tuo Intelletto totale." },
    [18560] = { en = "The purification of tainted Felcloth into Mooncloth can only be done at a moonwell, and only once every $s2 days will the waters permit themselves to be used in such a way.", description = "La purificazione della Vilstoffa contaminata in Telaluna si può compiere solo presso un Pozzo Lunare e una volta ogni $s2 giorni, quando le acque lo consentono." },
    [18633] = { en = "Deals $s1 Shadow damage every $t1 sec for $d and lowers their attack power by $s2 for $d.", description = "Infligge $s1 danni da ombra ogni $t1 sec. per $d e riduce di $s2 la potenza d’attacco del bersaglio per $d." },
    [18652] = { en = "Deals $s1 Shadow damage every $t1 sec for $d. All damage done is then transferred to the caster.", description = "Infligge $s1 danni da ombra ogni $t1 sec. per $d. Tutti i danni sono trasferiti all’incantatore." },
    [18694] = { en = "Increases the damage of your Imp's Firebolt spell by $s2% and the effect of its Fire Shield spell by $s1%.", description = "Aumenta del $s2% i danni di Dardo di Fuoco del tuo Imp e del $s1% l’effetto del suo Scudo di Fuoco." },
    [18697] = { en = "Increases your total Stamina by $s1%.", description = "Aumenta del $s1% la tua Tempra totale." },
    [18703] = { en = "Increases the amount of health transferred by your Health Funnel spell by $m1%, reduces its health cost by $m2%, and reduces all threat your Health Funnel generates by $m3%. Allows Health Funnel to be used regardless of your demon's health.", description = "Aumenta del $m1% la salute trasferita da Vincolo Vitale, riduce del $m2% il costo in salute e del $m3% la minaccia generata. Puoi usarlo indipendentemente dalla salute del demone." },
    [18705] = { en = "Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by $s1%.", description = "Aumenta del $s1% l’efficacia di Tormento, Consumo d’Ombre, Sacrificio e Sofferenza del Camminatore del Vuoto." },
    [18731] = { en = "Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by $s1%, and increases your maximum Mana by $s2%.", description = "Aumenta del $s1% la salute e il mana massimi di Imp, Camminatore del Vuoto, Succube, Incubo e Vilcacciatore, e del $s2% il tuo mana massimo." },
    [18754] = { en = "Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by $s1%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by $s2%.", description = "Aumenta del $s1% l’effetto di Frustata del Dolore e Bacio Lenitivo di Succube e Incubo e del $s2% la durata di Seduzione e Invisibilità Inferiore." },
    [18769] = { en = "Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by $s1%.", description = "Aumenta del $s1% tutti i danni inflitti dai tuoi Imp, Camminatore del Vuoto, Succube, Incubo e Vilcacciatore." },
    [18788] = { en = "When activated, sacrifices your summoned Demon to enhance the opposing aspect of your power, granting you an effect that lasts $18789d. The effect is canceled if any Demon is summoned.\r\n\r\nImp: Increases your Shadow damage by $18789s1%.\r\n\r\nVoidwalker: Restores $18792s1% of your total Mana every $18792t1 sec.\r\n\r\nSuccubus/Incubus: Increases your Fire damage by $18791s1%.\r\n\r\nFelhunter: Restores $18790s1% of your total Health every $18790t1 sec.", description = "Quando si attiva, sacrifica il demone evocato per potenziare l’aspetto opposto dei tuoi poteri; l’effetto dura $18789d e si annulla se evochi un demone.\r\n\r\nImp: aumenta del $18789s1% i danni da Ombra.\r\n\r\nCamminatore del Vuoto: ripristina il $18792s1% del mana totale ogni $18792t1 sec.\r\n\r\nSuccube/Incubo: aumenta del $18791s1% i danni da fuoco.\r\n\r\nVilcacciatore: ripristina il $18790s1% della salute totale ogni $18790t1 sec." },
    [18815] = { en = "When struck in melee combat, has a $h1% chance of stealing $18817s1 life from target enemy.", description = "Quando subisci un attacco in mischia, hai una probabilità del $h1% di sottrarre $18817s1 salute al nemico." },
    [18816] = { en = "When struck in combat has a $s1% chance of dealing $18818s1 Fire damage to all targets around you.", description = "Quando subisci un colpo in combattimento, hai una probabilità del $s1% di infliggere $18818s1 danni da fuoco ai bersagli vicini." },
    [18827] = { en = "Increases the damage done by your Bane of Agony by $s1%.", description = "Aumenta del $s1% i danni inflitti da Maledizione dell’Agonia." },
    [19028] = { en = "When active, $18814s1% of all damage taken by the caster is taken by your Imp, Voidwalker, Succubus, Incubus, or Felhunter Demon instead. In addition, both the Demon and the master will inflict $25228s1% more damage. Lasts as long as the Demon is active.", description = "Quando è attivo, il $18814s1% dei danni subiti dall’incantatore viene subito dal tuo Imp, Camminatore del Vuoto, Succube, Incubo o Vilcacciatore. Inoltre, demone e padrone infliggono il $25228s1% di danni aggiuntivi. Dura finché il demone è attivo." },
    [19159] = { en = "Increases the critical strike chance of all your melee abilities by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico delle tue abilità in mischia." },
    [19168] = { en = "Increases your Agility by $s1%.", description = "Aumenta del $s1% la tua Agilità." },
    [19184] = { en = "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for ${$m1/1000} sec.", description = "Quando le trappole si attivano, immobilizzano i bersagli colpiti per ${$m1/1000} sec." },
    [19228] = { en = "Gives your Wing Clip ability a $s1% chance to immobilize the target for $19229d.", description = "Conferisce a Falciata una probabilità del $s1% di immobilizzare il bersaglio per $19229d." },
    [19239] = { en = "Increases the duration of Freezing and Frost trap effects by $s1% and the damage of Immolation and Explosive trap effects by $s2%.", description = "Aumenta del $s1% la durata di Trappola congelante e Trappola del gelo e del $s2% i danni di Trappola immolante ed esplosiva." },
    [19255] = { en = "Increases your total Health by $s1%.", description = "Aumenta del $s1% la tua salute totale." },
    [19261] = { en = "The next melee attack against the caster will cause $19249s1 Shadow damage and reduce the attacker's melee attack power by $19249s2 for $19249d.", description = "Il prossimo attacco in mischia contro l’incantatore infligge $19249s1 danni da ombra e riduce di $19249s2 la potenza d’attacco in mischia dell’attaccante per $19249d." },
    [19262] = { en = "The next melee attack against the caster will cause $19251s1 Shadow damage and reduce the attacker's melee attack power by $19251s2 for $19251d.", description = "Il prossimo attacco in mischia contro l’incantatore infligge $19251s1 danni da ombra e riduce di $19251s2 la potenza d’attacco in mischia dell’attaccante per $19251d." },
    [19263] = { en = "When activated, increases your Dodge and Parry chance by $s1% for $d.", description = "Quando si attiva, aumenta del $s1% la probabilità di schivare e parare per $d." },
    [19264] = { en = "The next melee attack against the caster will cause $19252s1 Shadow damage and reduce the attacker's melee attack power by $19252s2 for $19252d.", description = "Il prossimo attacco in mischia contro l’incantatore infligge $19252s1 danni da ombra e riduce di $19252s2 la potenza d’attacco in mischia dell’attaccante per $19252d." },
    [19265] = { en = "The next melee attack on the caster will cause $19253s1 Shadow damage and reduce the attacker's melee attack power by the attacker by $19253s2 for $19253d.", description = "Il prossimo attacco in mischia contro l’incantatore infligge $19253s1 danni da ombra e riduce di $19253s2 la potenza d’attacco in mischia dell’attaccante per $19253d." },
    [19266] = { en = "The next melee attack on the caster will cause $19254s1 Shadow damage and reduce the attacker's melee attack power by the attacker by $19254s2 for $19254d.", description = "Il prossimo attacco in mischia contro l’incantatore infligge $19254s1 danni da ombra e riduce di $19254s2 la potenza d’attacco in mischia dell’attaccante per $19254d." },
    [19271] = { en = "The priest becomes surrounded with anti-magic energy.  Any successful spell cast against the priest will burn $19267s1 of the attacker's Mana, causing 1 Shadow damage for each point of Mana burned.  Lasts $d.", description = "Il Sacerdote è avvolto da energia antimagia. Ogni incantesimo che lo colpisce brucia $19267s1 mana dell’attaccante e infligge 1 danno da ombra per punto di mana bruciato. Dura $d." },
    [19273] = { en = "The priest becomes surrounded with anti-magic energy.  Any successful spell cast against the priest will burn $19268s1 of the attacker's Mana, causing 1 Shadow damage for each point of Mana burned.  Lasts $d.", description = "Il Sacerdote è avvolto da energia antimagia. Ogni incantesimo che lo colpisce brucia $19268s1 mana dell’attaccante e infligge 1 danno da ombra per punto di mana bruciato. Dura $d." },
    [19274] = { en = "The priest becomes surrounded with anti-magic energy.  Any successful spell cast against the priest will burn $19269s1 of the attacker's Mana, causing 1 Shadow damage for each point of Mana burned.  Lasts $d.", description = "Il Sacerdote è avvolto da energia antimagia. Ogni incantesimo che lo colpisce brucia $19269s1 mana dell’attaccante e infligge 1 danno da ombra per punto di mana bruciato. Dura $d." },
    [19290] = { en = "Increases your hit chance by $m3% and reduces the duration of movement impairing effects on you by $m2%.", description = "Aumenta del $m3% la probabilità di colpire e riduce del $m2% la durata degli effetti che limitano i tuoi movimenti." },
    [19308] = { en = "The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28378s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description = "L’incantatore è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza lo colpisce, l’attaccante subisce $28378s1 danni da ombra. Ogni attaccante può subirli solo ogni pochi secondi. Non generano minaccia. $n cariche. Dura $d." },
    [19309] = { en = "The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28379s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description = "L’incantatore è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza lo colpisce, l’attaccante subisce $28379s1 danni da ombra. Ogni attaccante può subirli solo ogni pochi secondi. Non generano minaccia. $n cariche. Dura $d." },
    [19310] = { en = "The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28380s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description = "L’incantatore è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza lo colpisce, l’attaccante subisce $28380s1 danni da ombra. Ogni attaccante può subirli solo ogni pochi secondi. Non generano minaccia. $n cariche. Dura $d." },
    [19311] = { en = "The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28381s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description = "L’incantatore è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza lo colpisce, l’attaccante subisce $28381s1 danni da ombra. Ogni attaccante può subirli solo ogni pochi secondi. Non generano minaccia. $n cariche. Dura $d." },
    [19312] = { en = "The caster is surrounded by shadows.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $28382s1 Shadow damage.  Attackers can only be damaged once every few seconds.  This damage causes no threat.  $n charges.  Lasts $d.", description = "L’incantatore è avvolto dalle ombre. Quando un incantesimo o un attacco in mischia o a distanza lo colpisce, l’attaccante subisce $28382s1 danni da ombra. Ogni attaccante può subirli solo ogni pochi secondi. Non generano minaccia. $n cariche. Dura $d." },
    [19370] = { en = "Increases your critical strike chance with all attacks by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico di tutti i tuoi attacchi." },
    [19376] = { en = "Increases your chance to hit with your Trap and Feign Death abilities by $s1%.", description = "Aumenta del $s1% la probabilità di colpire con Trappola e Finta Morte." },
    [19407] = { en = "Gives your Concussive Shot a $m1% chance to stun the target for $19410d.", description = "Conferisce a Tiro concussivo una probabilità del $m1% di stordire il bersaglio per $19410d." },
    [19416] = { en = "Reduces the Mana cost of your Shots, Stings, and melee abilities by $s1%.", description = "Riduce del $s1% il costo in mana di Tiri, Morsi e abilità in mischia." },
    [19421] = { en = "Increases the Ranged Attack Power bonus of your Hunter's Mark spell by $s1%.", description = "Aumenta del $s1% il bonus alla potenza d’attacco a distanza di Marchio del Cacciatore." },
    [19461] = { en = "Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by $s1%.", description = "Aumenta del $s1% i danni di Tiro Multiplo, Tiro Mirato e Raffica." },
    [19464] = { en = "Increases the damage done by your Serpent Sting by $s1%.", description = "Aumenta del $s1% i danni di Puntura di Serpente." },
    [19474] = { en = "Calls down a fiery rain to burn enemies in the area of effect for ${4*$1282381m1} Fire damage over $d.", description = "Scatena una pioggia infuocata che brucia i nemici nell’area, infliggendo ${4*$1282381m1} danni da fuoco in $d." },
    [19478] = { en = "Taints the Felhunter's blood for $d.  When the Felhunter is hit with a melee attack, the attacker will lose $19479s1 melee attack power for $19479d.  Stacks up to 5 times on a single target.", description = "Contamina il sangue del Vilcacciatore per $d. Quando viene colpito in mischia, l’attaccante perde $19479s1 potenza d’attacco in mischia per $19479d. Si cumula fino a 5 volte sullo stesso bersaglio." },
    [19480] = { en = "Increases the stealth detection of all party members within $a1 yds of the Felhunter as if they were ${$m1/5} levels higher.", description = "Aumenta la rilevazione della furtività del gruppo entro $a1 metri dal Vilcacciatore, come se avesse ${$m1/5} livelli in più." },
    [19485] = { en = "Increases the critical strike damage bonus on all ranged abilities by $m1%.", description = "Aumenta del $m1% il bonus ai danni critici di tutte le abilità a distanza." },
    [19498] = { en = "Increases the range of your ranged weapons by $s1 yards.", description = "Aumenta di $s1 metri la gittata delle tue armi a distanza." },
    [19505] = { en = "Purges $s1 harmful magic $leffect:effects; from a friend or $s1 beneficial magic $leffect:effects; from an enemy.  If an effect is devoured, the Felhunter will be healed for $19658s1.", description = "Dissolve $s1 $leffect:effects; effetti magici dannosi da un alleato oppure $s1 $leffect:effects; effetti magici benefici da un nemico. Se l’effetto viene dissolto, il Vilcacciatore recupera $19658s1 salute." },
    [19507] = { en = "Increases the damage you deal with ranged weapons by $s1%.", description = "Aumenta del $s1% i danni che infliggi con le armi a distanza." },
    [19549] = { en = "Increases the Dodge bonus of your Aspect of the Monkey by $s1%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability.", description = "Aumenta del $s1% il bonus alla schivata di Aspetto della Scimmia. Inoltre, il famiglio ottiene il 50% dell’effetto." },
}
for spellID, entry in pairs(frequentSpellDescriptions) do
    ns.data.spellDescriptionOverrides[spellID] = entry
end
